        Item("S193", "Q", "Authentic first mention.", "ON: traceable independent accounts discuss the token before substantial price breakout; OFF: observed mentions are recycled promotions or timestamped after move.", Kind.EVIDENCE, emptyList()),
        Item("S194", "Q", "Attention velocity.", "ON: unique independent social authors referencing exact mint increase over several windows; OFF: only bot repost volume grows.", Kind.EVIDENCE, emptyList()),
